<section class="page-header"><div><a class="back-link" href="<?= url('estimates') ?>"><i class="fa-solid fa-arrow-left"></i> Back to estimates</a><h1>Create estimate</h1><p>Line totals and tax are recalculated securely on the server.</p></div></section>
<form method="post" action="<?= url('estimates') ?>" id="estimateForm"><?= csrf_field() ?><div class="invoice-form-layout"><section class="panel form-panel"><div class="form-section"><h3>Estimate details</h3><div class="form-grid"><label>Client *<select name="client_id" id="estimateClient" required><option value="">Select client</option><?php foreach($clients as $c):?><option value="<?= $c['id'] ?>"><?= e($c['company_name']) ?></option><?php endforeach;?></select></label><label>Project<select name="project_id" id="estimateProject"><option value="">General proposal</option><?php foreach($projects as $p):?><option value="<?= $p['id'] ?>" data-client="<?= $p['client_id'] ?>"><?= e($p['name']) ?></option><?php endforeach;?></select></label><label>Document type<select name="estimate_type"><option>Quotation</option><option>Estimate</option><option>Proforma</option></select></label><label>Estimate date *<input type="date" name="estimate_date" value="<?= date('Y-m-d') ?>" required></label><label>Valid until<input type="date" name="valid_until" value="<?= date('Y-m-d',strtotime('+30 days')) ?>"></label><label>Overall discount<input type="number" name="discount_total" value="0" min="0" step="0.01" data-estimate-summary></label></div></div><div class="form-section"><div class="section-title-row"><h3>Line items</h3><button class="button button-secondary button-sm" type="button" id="addEstimateItem"><i class="fa-solid fa-plus"></i> Add line</button></div><div class="invoice-items" id="estimateItems"><div class="invoice-item estimate-item" data-row="0"><label class="item-description">Description *<input name="items[0][description]" required placeholder="Service, deliverable or milestone"></label><label>Qty<input type="number" name="items[0][quantity]" value="1" min="0.01" step="0.01" required data-estimate-calc></label><label>Rate<input type="number" name="items[0][rate]" value="0" min="0" step="0.01" required data-estimate-calc></label><label>Tax %<input type="number" name="items[0][tax_percent]" value="18" min="0" max="100" step="0.01" data-estimate-calc></label><div class="item-total"><span>Line total</span><strong>₹0.00</strong></div><button class="icon-button danger remove-estimate-line" type="button" title="Remove"><i class="fa-solid fa-xmark"></i></button></div></div></div><div class="form-section"><div class="form-grid"><label class="wide">Notes<textarea name="notes" rows="3" placeholder="Scope notes visible on the estimate"></textarea></label><label class="wide">Terms<textarea name="terms" rows="3">This quotation is valid until the date shown. Work begins after written acceptance.</textarea></label></div></div></section><aside class="panel invoice-summary"><h3>Estimate summary</h3><dl><div><dt>Subtotal</dt><dd id="estimateSubtotal">₹0.00</dd></div><div><dt>Tax</dt><dd id="estimateTax">₹0.00</dd></div><div><dt>Discount</dt><dd id="estimateDiscount">₹0.00</dd></div><div class="summary-total"><dt>Grand total</dt><dd id="estimateGrand">₹0.00</dd></div></dl><div class="inline-alert info"><i class="fa-solid fa-calculator"></i> Final values are recalculated on submission.</div><button class="button button-primary button-block"><i class="fa-solid fa-file-circle-plus"></i> Create draft estimate</button><a class="button button-secondary button-block" href="<?= url('estimates') ?>">Cancel</a></aside></div></form>
<script>document.addEventListener('DOMContentLoaded',()=>{const box=document.getElementById('estimateItems'),money=n=>'₹'+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});let next=1;const recalc=()=>{let subtotal=0,tax=0;box.querySelectorAll('.estimate-item').forEach(row=>{const q=+(row.querySelector('[name$="[quantity]"]').value||0),r=+(row.querySelector('[name$="[rate]"]').value||0),t=+(row.querySelector('[name$="[tax_percent]"]').value||0),base=q*r,taxValue=base*t/100;subtotal+=base;tax+=taxValue;row.querySelector('.item-total strong').textContent=money(base+taxValue)});const discount=+(document.querySelector('[name=discount_total]').value||0);document.getElementById('estimateSubtotal').textContent=money(subtotal);document.getElementById('estimateTax').textContent=money(tax);document.getElementById('estimateDiscount').textContent=money(discount);document.getElementById('estimateGrand').textContent=money(Math.max(0,subtotal+tax-discount))};box.addEventListener('input',recalc);document.querySelector('[data-estimate-summary]').addEventListener('input',recalc);document.getElementById('addEstimateItem').addEventListener('click',()=>{const row=box.firstElementChild.cloneNode(true);row.dataset.row=next;row.querySelectorAll('input').forEach(input=>{input.name=input.name.replace(/items\[\d+]/,`items[${next}]`);input.value=input.name.endsWith('[quantity]')?'1':input.name.endsWith('[tax_percent]')?'18':''});row.querySelector('.item-total strong').textContent='₹0.00';box.append(row);next++;recalc()});box.addEventListener('click',e=>{const button=e.target.closest('.remove-estimate-line');if(button&&box.children.length>1){button.closest('.estimate-item').remove();recalc()}});document.getElementById('estimateClient').addEventListener('change',e=>document.querySelectorAll('#estimateProject option[data-client]').forEach(o=>o.hidden=o.dataset.client!==e.target.value));recalc()});</script>
